<?php
require '/var/www/html/vendor/autoload.php';$app=require '/var/www/html/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;
$payload=json_decode(file_get_contents('/tmp/ent-cleanup-data.json'),true);$sessions=[$payload['admin_session']];$visitors=[];
foreach($payload['cookies'] as $c){if(!in_array($c['name'],[config('session.cookie'),config('jakawi.analytics.visitor_cookie')]))continue;$v=Illuminate\Support\Str::isUuid($c['value'])?$c['value']:Illuminate\Cookie\CookieValuePrefix::remove(app('encrypter')->decrypt(rawurldecode($c['value']),false));if($c['name']===config('session.cookie')){if(!preg_match('/^[a-zA-Z0-9]{40}$/',$v))throw new RuntimeException('Invalid session');$sessions[]=$v;}else{if(!Illuminate\Support\Str::isUuid($v))throw new RuntimeException('Invalid visitor');$visitors[]=$v;}}
$sessions=array_unique($sessions);$visitors=array_unique($visitors);
$result=DB::transaction(function()use($visitors,$sessions){if(App\Models\AttributionTouch::whereIn('anonymous_id',$visitors)->exists())throw new RuntimeException('Unexpected attribution; inspect before cleanup');$n=App\Models\AnalyticsEvent::whereIn('visitor_id',$visitors)->delete();$s=DB::table('sessions')->whereIn('id',$sessions)->delete();return ['status'=>'PASS','events_removed'=>$n,'sessions_removed'=>$s,'events_remaining'=>App\Models\AnalyticsEvent::whereIn('visitor_id',$visitors)->count(),'sessions_remaining'=>DB::table('sessions')->whereIn('id',$sessions)->count(),'commercial_data_modified'=>false];});echo json_encode($result,JSON_PRETTY_PRINT);
